import React, { useState, useEffect } from "react";
import { collection, addDoc, getDocs, deleteDoc, doc, updateDoc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./ManageTeachers.css";

const AdminManageTeachers = () => {
  const [teachers, setTeachers] = useState([]);
  const [form, setForm] = useState({
    name: "",
    email: "",
    username: "",
    password: "",
    subject: "",
  });
  const [editId, setEditId] = useState(null);

  const TeachersCollectionRef = collection(db, "teachers");

  const fetchTeachers = async () => {
    const data = await getDocs(TeachersCollectionRef);
    setTeachers(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
  };

  useEffect(() => {
    fetchTeachers();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });
  };

  const addOrUpdateTeacher = async (e) => {
    e.preventDefault();
    if (editId) {
      const teacherDoc = doc(db, "teachers", editId);
      await updateDoc(teacherDoc, form);
    } else {
      await addDoc(TeachersCollectionRef, form);
    }
    fetchTeachers();
    setForm({ name: "", email: "", username: "", password: "", subject: "" });
    setEditId(null);
  };

  const deleteTeacher = async (id) => {
    const teacherDoc = doc(db, "teachers", id);
    await deleteDoc(teacherDoc);
    fetchTeachers();
  };

  const editTeacher = (teacher) => {
    setForm(teacher);
    setEditId(teacher.id);
  };

  const subjects = [
    "Mathematics", "English Language", "Science", "Social Studies", "Civic Education",
    "Agricultural Science", "Home Economics", "Computer Studies", "Physical Education",
    "Business Studies", "Geography", "History", "Religious Studies", "Economics",
    "Government", "Physics", "Chemistry", "Biology", "Fine Arts", "Music", "Technical Drawing"
  ];

  return (
    <div className="page-container">
      <div className="manage-students-container">
        <h2>Manage Teachers</h2>
        <form onSubmit={addOrUpdateTeacher} className="student-form">
          {/* Form Fields */}
          <label htmlFor="name">Name:</label>
          <input
            type="text"
            id="name"
            name="name"
            value={form.name}
            onChange={handleInputChange}
            required
          />
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            value={form.email}
            onChange={handleInputChange}
            required
          />
          <label htmlFor="username">Username:</label>
          <input
            type="text"
            id="username"
            name="username"
            value={form.username}
            onChange={handleInputChange}
            required
          />
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            name="password"
            value={form.password}
            onChange={handleInputChange}
            required
          />
          <label htmlFor="subject">Subject:</label>
          <select
            id="subject"
            name="subject"
            value={form.subject}
            onChange={handleInputChange}
            required
          >
            <option value="" disabled>
              Select Subject
            </option>
            {subjects.map((subject, index) => (
              <option key={index} value={subject}>
                {subject}
              </option>
            ))}
          </select>
          <button type="submit" className="form-btn">
            {editId ? "Update Teacher" : "Add Teacher"}
          </button>
        </form>
        <table className="students-table">
          {/* Table */}
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Username</th>
              <th>Subject</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {teachers.map((teacher) => (
              <tr key={teacher.id}>
                <td>{teacher.name}</td>
                <td>{teacher.email}</td>
                <td>{teacher.username}</td>
                <td>{teacher.subject}</td>
                <td>
                  <button onClick={() => editTeacher(teacher)} className="edit-btn">
                    Edit
                  </button>
                  <button onClick={() => deleteTeacher(teacher.id)} className="delete-btn">
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <footer className="footer">
        <p>&copy; 2025 Your School Management System</p>
      </footer>
    </div>
  );
};

export default AdminManageTeachers;
